package dev.industrialtechnology.test;
import java.util.*;import java.io.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.lang.reflect.*;
import cpw.mods.fml.common.*;import cpw.mods.fml.common.gameevent.TickEvent;import cpw.mods.fml.common.eventhandler.SubscribeEvent;
import dev.industrialtechnology.capacitor.*;import dev.industrialtechnology.client.*;import dev.industrialtechnology.core.*;import dev.industrialtechnology.steel.*;
import net.minecraft.client.*;import net.minecraft.client.gui.*;import net.minecraft.entity.player.EntityPlayerMP;import net.minecraft.server.MinecraftServer;import net.minecraft.world.*;import net.minecraft.item.*;import net.minecraft.nbt.*;import net.minecraft.init.*;import net.minecraft.util.ScreenShotHelper;import org.lwjgl.opengl.GL11;
public final class SteelClientChecks {
    private final List<String> report=Collections.synchronizedList(new ArrayList<String>());private int phase,wait=30,age;private boolean done;private volatile boolean ready,failed;
    public void init(){FMLCommonHandler.instance().bus().register(this);}
    private static void check(boolean b,String s){if(!b)throw new AssertionError(s);}
    private void pass(String s){report.add("PASS: "+s);}
    private static EntityPlayerMP player(){return (EntityPlayerMP)MinecraftServer.getServer().getConfigurationManager().playerEntityList.get(0);}
    private static WorldServer world(){return (WorldServer)player().worldObj;}
    private void server(Runnable r){ServerWork.enqueue(()->{try{r.run();}catch(Throwable e){failed=true;report.add("FAIL: server :: "+e);IndustrialTechnology.log.error("Steel fixture",e);}});}
    private static void shot(Minecraft mc,String name){ScreenShotHelper.saveScreenshot(mc.mcDataDir,name,mc.displayWidth,mc.displayHeight,mc.getFramebuffer());}
    private static void fill(TileCapacitorBank b,long rf){ItemStack s=new ItemStack(ModRegistry.capacitorBank);NBTTagCompound n=new NBTTagCompound();n.setInteger("BankVersion",1);n.setLong("StoredRF",rf);s.setTagCompound(n);b.restoreItem(s);}
    @SubscribeEvent public void tick(TickEvent.ClientTickEvent e){if(done||e.phase!=TickEvent.Phase.END||--wait>0)return;Minecraft mc=Minecraft.getMinecraft();try{
        if(failed){finish();return;}
        if(phase==0){if(!(mc.currentScreen instanceof GuiMainMenu)){wait=20;return;}mc.gameSettings.guiScale=3;mc.gameSettings.renderDistanceChunks=3;mc.gameSettings.pauseOnLostFocus=false;mc.gameSettings.showInventoryAchievementHint=false;WorldSettings s=new WorldSettings(25,WorldSettings.GameType.CREATIVE,false,false,WorldType.FLAT);s.func_82750_a("2;7;1;");mc.launchIntegratedServer("steel-client","Disposable factory visual QA",s);phase=1;wait=70;return;}
        if(mc.thePlayer==null||mc.theWorld==null){if(++age>100)throw new AssertionError("join timeout");wait=10;return;}
        if(phase==1){mc.displayGuiScreen(null);TooltipClientChecks.prepare(mc);server(()->{WorldServer w=world();EntityPlayerMP p=player();for(int x=20;x<=28;x+=2){w.setBlock(x,71,24,Blocks.stone,0,3);w.setBlock(x,72,24,ModRegistry.capacitorBank,3,3);TileCapacitorBank b=(TileCapacitorBank)w.getTileEntity(x,72,24);if(x==20)b.setSide(3,0);if(x==22)b.setSide(3,1);if(x==24){fill(b,25000000);b.toggleGauge(3);}if(x==26){fill(b,12500000);b.toggleGauge(3);}}
            w.setBlock(30,72,24,SteelRegistry.factory,3,3);TileSteelFactory t=(TileSteelFactory)w.getTileEntity(30,72,24);t.setInventorySlotContents(0,new ItemStack(Items.iron_ingot,64));t.setInventorySlotContents(2,new ItemStack(com.hbm.items.ModItems.powder_coal,16));t.setInventorySlotContents(8,new ItemStack(com.hbm.items.ModItems.upgrade_speed_1));t.setInventorySlotContents(9,new ItemStack(com.hbm.items.ModItems.upgrade_power_1));t.setPower(987654);w.setBlock(32,72,24,SteelRegistry.factory,3,3);w.setBlock(34,72,24,com.hbm.blocks.ModBlocks.machine_difurnace_rtg_off,3,3);p.capabilities.allowFlying=true;p.capabilities.isFlying=true;p.sendPlayerAbilities();p.playerNetServerHandler.setPlayerLocation(27,74,34,180,9);ready=true;});phase=2;wait=70;return;}
        if(phase==2){if(!ready){wait=10;return;}check(GL11.glGetError()==0,"world GL error");for(int side=0;side<6;side++){check(SteelRegistry.factory.getIcon(side,3).getIconName().equals(com.hbm.blocks.ModBlocks.machine_difurnace_rtg_off.getIcon(side,3).getIconName()),"HBM inactive texture differs on face "+side);check(SteelRegistry.factory.getIcon(side,11).getIconName().equals(com.hbm.blocks.ModBlocks.machine_difurnace_rtg_on.getIcon(side,3).getIconName()),"HBM active texture differs on face "+side);}pass("All six active and inactive factory faces use exactly the installed HBM Nuclear Blast Furnace LEGACY texture atlas");
            check((mc.theWorld.getBlockMetadata(30,72,24)&8)!=0&&(mc.theWorld.getBlockMetadata(32,72,24)&8)==0,"active appearance packet");pass("Server processing synchronizes the working furnace appearance; idle factory retains inactive artwork");shot(mc,"bank-green-red-gold-world.png");pass("Cached world mesh renders green input plus, red output minus, gold full gauge and partial gauge");server(()->{player().playerNetServerHandler.setPlayerLocation(30,72,27,180,0);player().openGui(IndustrialTechnology.instance,6,world(),30,72,24);});phase=3;wait=35;return;}
        if(phase==3){check(mc.currentScreen instanceof GuiSteelFactory,"factory GUI missing");GuiSteelFactory g=(GuiSteelFactory)mc.currentScreen;check(g.steel.shownPower>65535&&g.steel.factory.getStackInSlot(0)!=null,"HE or slot synchronization");check(g.steel.factory.getStackInSlot(8)!=null&&g.steel.factory.getStackInSlot(9)!=null&&g.steel.shownHE==850&&g.steel.shownTicks==85,"upgrade inventory/profile packet");pass("Two actual HBM upgrades and their combined time and HE/t synchronize through ordinary GUI packets");shot(mc,"steel-factory-gui.png");TooltipClientChecks.steel(mc,g,this::pass);pass("Real container packets display HE above 65535 and synchronize iron, coal and HBM steel slots");check(GL11.glGetError()==0,"factory GL error");pass("Factory and actual NEI item panel render with no OpenGL errors");server(()->{player().closeScreen();player().playerNetServerHandler.setPlayerLocation(24,72,27,180,0);player().openGui(IndustrialTechnology.instance,2,world(),24,72,24);});phase=4;wait=30;return;}
        if(phase==4){check(mc.currentScreen instanceof GuiCapacitorBank,"bank GUI missing");GuiCapacitorBank g=(GuiCapacitorBank)mc.currentScreen;check(g.state.getLong("Stored")==g.state.getLong("Capacity")&&g.state.getLong("Capacity")==25000000,"not full");shot(mc,"bank-full-gold-gui.png");pass("Bank GUI retains exact RF statistics and displays gold at full capacity");TooltipClientChecks.bank(mc,g,this::pass);check(GL11.glGetError()==0,"bank GL error");pass("Bank colored controls preserve tooltip lighting and NEI rendering");check(codechicken.nei.recipe.GuiCraftingRecipe.openRecipeGui("item",new ItemStack(com.hbm.items.ModItems.ingot_steel)),"steel recipe screen unavailable");selectRecipe(mc);phase=5;wait=20;return;}

        if(phase==5){check(mc.currentScreen instanceof codechicken.nei.recipe.GuiCraftingRecipe,"NEI crafting closed");codechicken.nei.recipe.GuiRecipe g=(codechicken.nei.recipe.GuiRecipe)mc.currentScreen;codechicken.nei.recipe.IRecipeHandler h=g.getCurrentRecipeHandlers().get(g.recipetype);check(h instanceof dev.industrialtechnology.integration.nei.BulkSteelRecipeHandler,"wrong handler");check(h.getResultStack(0).item.getItem()==com.hbm.items.ModItems.ingot_steel&&h.getResultStack(0).item.stackSize==16,"wrong NEI output");java.util.List<codechicken.nei.PositionedStack> inputs=h.getIngredientStacks(0);check(inputs.size()==2&&inputs.get(0).item.stackSize==16&&inputs.get(1).item.stackSize==4,"wrong NEI inputs");shot(mc,"nei-bulk-steel-recipe.png");pass("Looking up genuine HBM steel in real NEI includes the factory recipe, counted inputs/output and HE/time details");check(codechicken.nei.recipe.GuiUsageRecipe.openRecipeGui("item",new ItemStack(Items.iron_ingot)),"iron usage unavailable");selectRecipe(mc);phase=6;wait=20;return;}
        if(phase==6){check(mc.currentScreen instanceof codechicken.nei.recipe.GuiUsageRecipe,"NEI usage closed");shot(mc,"nei-iron-factory-usage.png");check(GL11.glGetError()==0,"NEI recipe GL error");pass("NEI iron usage lookup also includes the steel factory; original HBM recipes remain alongside it");finish();}
    }catch(Throwable ex){failed=true;report.add("FAIL: client phase "+phase+" :: "+ex);IndustrialTechnology.log.error("Steel client",ex);finish();}}
    private void selectRecipe(Minecraft mc){codechicken.nei.recipe.GuiRecipe g=(codechicken.nei.recipe.GuiRecipe)mc.currentScreen;java.util.List<? extends codechicken.nei.recipe.IRecipeHandler> handlers=g.getCurrentRecipeHandlers();for(int i=0;i<handlers.size();i++)if(handlers.get(i) instanceof dev.industrialtechnology.integration.nei.BulkSteelRecipeHandler){g.recipetype=i;g.page=0;g.refreshPage();return;}throw new AssertionError("Factory recipe not discovered by NEI (handlers "+handlers.size()+")");}
    private void finish(){if(done)return;done=true;try{report.add("Failed: "+(failed?1:0));Files.write(new File(Minecraft.getMinecraft().mcDataDir,"steel-client-report.txt").toPath(),report,StandardCharsets.UTF_8);}catch(Exception e){IndustrialTechnology.log.error("Steel client report",e);}Minecraft.getMinecraft().shutdown();}
}
